// ---- story (chapter Ch4, ch4 agent 2026-10-07: Sapphire data/maps/FallarborTown_House2/scripts.inc; generators keep everything
// from this line on; entries above marked "// story:"). The Move Tutor: data/story/ch4.json uid 1. Text: lines 1-8
// (line 0 is the generator's placeholder). Sapphire's SelectMoveTutorMon / DisplayMoveTutorMenu = Black 2's own Move
// Reminder (its global 1235 Script_2): CallPokeSelect, PokePartyIsEgg, MoveReminderCheckPkm (0 = nothing to remember),
// MoveReminderCallMoveSelect (0 = a move was learned, 1 = cancelled).
#define T_ImTheMoveTutor 1      // FallarborTown_MoveRelearnersHouse_Text_ImTheMoveTutor
#define T_HeartScale 2          // FallarborTown_MoveRelearnersHouse_Text_ThatsAHeartScaleWantMeToTeachMove
#define T_WhichMon 3            // FallarborTown_MoveRelearnersHouse_Text_TutorWhichMon
#define T_WhichMove 4           // FallarborTown_MoveRelearnersHouse_Text_TeachWhichMove
#define T_HandedOver 5          // FallarborTown_MoveRelearnersHouse_Text_HandedOverHeartScale
#define T_NoMove 6              // FallarborTown_MoveRelearnersHouse_Text_DontHaveMoveToTeachPokemon
#define T_CantTeachEgg 7        // FallarborTown_MoveRelearnersHouse_Text_CantTeachEgg
#define T_ComeBack 8            // FallarborTown_MoveRelearnersHouse_Text_ComeBackWithHeartScale
#define FH2_TEMP_1 0x5A         // FLAG_TEMP_1 (map-local: Black 2 clears flags 0-0x63 on every zone change)
#define FH2_SLOT 0x803A

FH2_MoveRelearner:                          // FallarborTown_MoveRelearnersHouse_EventScript_MoveRelearner
    c4_talk
    h_goto_if_set FH2_TEMP_1, L_FH2_Ask
    h_msgbox T_ImTheMoveTutor
    h_setflag FH2_TEMP_1
L_FH2_Ask:                                  // ..._AskTeachMove
    h_checkitem ITEM_HEART_SCALE, 1, C4_TMP
    h_goto_if_eq C4_TMP, 0, L_FH2_ComeBack
    h_yesno T_HeartScale, C4_TMP
    h_goto_if_no C4_TMP, L_FH2_ComeBack
L_FH2_ChooseMon:                            // ..._ChooseMon
    h_msgbox T_WhichMon
    h_closemessage
    CallPokeSelect 0, C4_TMP, FH2_SLOT, 0   // special SelectMoveTutorMon
    h_goto_if_eq C4_TMP, 0, L_FH2_ComeBack  // (nobody chosen)
    PokePartyIsEgg C4_TMP, FH2_SLOT
    h_goto_if_eq C4_TMP, 1, L_FH2_Egg
    MoveReminderCheckPkm C4_TMP, FH2_SLOT
    h_goto_if_eq C4_TMP, 0, L_FH2_NoMove
    h_msgbox T_WhichMove                    // ..._ChooseMove
    h_closemessage
    MoveReminderCallMoveSelect C4_TMP, FH2_SLOT   // special DisplayMoveTutorMenu
    h_goto_if_ne C4_TMP, 0, L_FH2_ChooseMon // cancelled: choose again
    WordSetPlayerName 0
    h_msgbox T_HandedOver
    h_removeitem ITEM_HEART_SCALE, 1, C4_TMP
L_FH2_ComeBack:
    h_msgbox T_ComeBack
    h_release
L_FH2_NoMove:
    h_msgbox T_NoMove
    VMJump L_FH2_ChooseMon
L_FH2_Egg:
    h_msgbox T_CantTeachEgg
    VMJump L_FH2_ChooseMon
    .balign 4, 0
